from pathlib import Path
import zipfile,json,hashlib
B=Path(__file__).resolve().parents[1]
OUT=B/'Chapter_5_Lettering_Source_Checkpoint.zip'
readme='''My Summons Go First — Chapter 5: The Way Around\nIncremental lettering source checkpoint, not a complete chapter or publication.\n\nThe exact reviewed script and all38 acting units are included. Independently accepted panels29–35 have been lettered in this checkpoint. The provisional reader contains that continuous seven-panel subset. The chapter is incomplete; all other panels await accepted art and lettering. Panel36 artwork is retained provisionally but was rejected for an extra grip digit and is excluded from the reader.\n\nRaw artist sheets, exact selected crops, prompts, independent raw-art QA, reproducible assembly source, placement manifest, raster lettering and actual compressed-reader QA are retained. Adjacent panels present on artist sheets remain unreleased unless the QA ledger explicitly approves them.\n\nDialogue is rasterized using the locally licensed official Blambot Anime Ace2BB font. No font program, font archive or embedded PDF font is redistributed. Rebuilding requires a separately licensed local font supplied using ANIME_ACE_FONT.\n\nAll balloon shapes are native assembly geometry over intact imagegen art. Native imagegen phone/UI lettering, when present in future panels, is retained in the art and will not be duplicated. No art was generated by the assembler. No website or other chapter was edited.\n'''
accepted=sorted(map(int,json.loads((B/'source/layout_config.json').read_text())['panels']))
readme='My Summons Go First — Chapter5: The Way Around\nINCOMPLETE SOURCE CHECKPOINT\n\nIncluded lettered panels: '+', '.join(map(str,accepted))+'. See readiness_matrix.json and independent review reports for exact scope. Missing panels remain pending; this is not a completed reader or publication.\n\n'+'Raw artist sheets,'+readme.split('Raw artist sheets,',1)[1]
files={}
for folder in ['source','raw','repairs','qa','lettered']:
 for p in (B/folder).rglob('*'):
  if p.is_file() and '__pycache__' not in p.parts and p.suffix.lower() not in ('.otf','.ttf','.woff','.woff2','.zip','.pyc'):
   data=p.read_bytes();rel=str(p.relative_to(B))
   if rel=='source/layout_config.json':
    obj=json.loads(data);obj['font_path']='';data=json.dumps(obj,indent=2).encode()
   files[rel]=data
files['README.txt']=readme.encode()
index={k:{'sha256':hashlib.sha256(v).hexdigest(),'bytes':len(v)} for k,v in files.items()}
with zipfile.ZipFile(OUT,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for k,v in files.items():z.writestr('Chapter_5_Checkpoint/'+k,v)
 z.writestr('Chapter_5_Checkpoint/FILE_INDEX.json',json.dumps(index,indent=2))
print(OUT.resolve(),OUT.stat().st_size,hashlib.sha256(OUT.read_bytes()).hexdigest())
